def longest_run(items):
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return (None, 0, -1)

    best_value = current
    best_length = 1
    best_start = 0

    current_length = 1
    current_start = 0

    for index, value in enumerate(iterator, 1):
        if value == current:
            current_length += 1
        else:
            if current_length > best_length:
                best_value = current
                best_length = current_length
                best_start = current_start
            current = value
            current_length = 1
            current_start = index

    if current_length > best_length:
        best_value = current
        best_length = current_length
        best_start = current_start

    return (best_value, best_length, best_start)

def merge_intervals(intervals):
    sorted_intervals = sorted((min(a, b), max(a, b)) for a, b in intervals)

    merged = []
    for start, end in sorted_intervals:
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))

    return merged

def deep_merge(left, right):
    def clone(value):
        if isinstance(value, dict):
            return {clone(key): clone(item) for key, item in value.items()}
        if isinstance(value, list):
            return [clone(item) for item in value]
        return value

    if not isinstance(left, dict) or not isinstance(right, dict):
        return clone(right)

    result = {}
    for key, value in left.items():
        if key in right:
            right_value = right[key]
            if isinstance(value, dict) and isinstance(right_value, dict):
                result[clone(key)] = deep_merge(value, right_value)
            else:
                result[clone(key)] = clone(right_value)
        else:
            result[clone(key)] = clone(value)

    for key, value in right.items():
        if key not in left:
            result[clone(key)] = clone(value)

    return result

